"""Regenerate every report table and figure from the evaluation outputs (Week 11: "every number can be regenerated by a script").

    python scripts/make_figures.py                      # experiments/ -> report/results/ and report/figures/
    python scripts/make_figures.py --require-freeze     # refuse to run unless HEAD is the tagged, clean eval-freeze commit

Writes into --out (default report/results):
    summary_table.csv / .md / .json   the eight success targets of section 3.4: measured value, requirement, met / not met / not measured
    ablation_table.csv / .md          A1-A8: done or not run, with a one-line headline each
    faithfulness.csv / .md, auroc.csv TFR / FIR with 95% intervals and the detector AUROCs (scripts/eval_faithfulness.py)
    user_study.* (if study/responses.csv exists)
    provenance.json                   git commit, tags, whether the working tree was clean, versions, time
    <step>/...                        copies of every small CSV / JSON / Markdown result the evaluation scripts wrote
and report/figures/targets_overview.png (a colour-coded copy of the summary table). The per-step figures (RD curves, diffusion
grids, guidance, detectors) are written by the evaluation scripts themselves into report/figures/.

Nothing is recomputed and nothing is invented: a target whose evaluation has not been run shows as "not measured".
"""
import argparse
import json
import platform
import shutil
import subprocess
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
import pandas as pd  # noqa: E402
from truesight.analysis import report as R  # noqa: E402

COPY_SUFFIXES = {".csv", ".json", ".md", ".txt"}
MAX_COPY_BYTES = 5 * 2 ** 20
FREEZE_TAG = "eval-freeze"


def git(*args):
    try:
        r = subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True, timeout=30)
        return r.stdout.strip() if r.returncode == 0 else None
    except (OSError, subprocess.SubprocessError):
        return None


def provenance():
    commit = git("rev-parse", "HEAD")
    tags = (git("tag", "--points-at", "HEAD") or "").split()
    dirty = bool(git("status", "--porcelain", "--untracked-files=no"))
    info = dict(commit=commit, tags_at_head=tags, working_tree_dirty=dirty, frozen=bool(commit and FREEZE_TAG in tags and not dirty),
                python=platform.python_version(), generated=time.strftime("%Y-%m-%d %H:%M:%S UTC", time.gmtime()))
    try:
        import torch
        info["torch"] = torch.__version__
    except ImportError:
        pass
    return info


def copy_results(exp, out):
    n = 0
    for f in sorted(Path(exp).rglob("*")):
        if f.is_file() and f.suffix.lower() in COPY_SUFFIXES and f.stat().st_size <= MAX_COPY_BYTES and ".done" not in f.parts \
                and "logs" not in f.relative_to(exp).parts and "fid" not in f.relative_to(exp).parts:
            dst = Path(out) / f.relative_to(exp)
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(f, dst); n += 1
    return n


def overview_figure(targets, path):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    flags = [R._as_flag(m) for m in targets["met"]]
    color = {True: "#c8e6c9", False: "#ffcdd2", None: "#e0e0e0"}
    fig, ax = plt.subplots(figsize=(13, 0.55 * len(targets) + 1.2)); ax.axis("off")
    cells = [[r.target, r.requirement, r.measured, R.verdict_symbol(f)] for r, f in zip(targets.itertuples(), flags)]
    tb = ax.table(cellText=cells, colLabels=["Target", "Requirement", "Measured", "Result"], loc="center", cellLoc="left",
                  colWidths=[0.24, 0.27, 0.35, 0.12])
    tb.auto_set_font_size(False); tb.set_fontsize(8); tb.scale(1, 1.5)
    for i, f in enumerate(flags, 1):
        tb[i, 3].set_facecolor(color[f])
    ax.set_title("Success targets (section 3.4)", fontsize=11)
    fig.tight_layout(); Path(path).parent.mkdir(parents=True, exist_ok=True); fig.savefig(path, dpi=130); plt.close(fig)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--exp", default=str(ROOT / "experiments"))
    ap.add_argument("--out", default=str(ROOT / "report" / "results"))
    ap.add_argument("--figs", default=str(ROOT / "report" / "figures"))
    ap.add_argument("--study", default=str(ROOT / "study"))
    ap.add_argument("--require-freeze", action="store_true", help=f"exit unless HEAD is tagged {FREEZE_TAG} and the tree is clean")
    ap.add_argument("--no-copy", action="store_true", help="do not copy the per-step result files into --out")
    a = ap.parse_args()
    prov = provenance()
    if a.require_freeze and not prov["frozen"]:
        sys.exit(f"HEAD is not a clean commit tagged '{FREEZE_TAG}' (tags: {prov['tags_at_head']}, dirty: {prov['working_tree_dirty']}); "
                 f"run: git tag {FREEZE_TAG}  after committing everything")
    out = Path(a.out); out.mkdir(parents=True, exist_ok=True)

    targets = R.collect_targets(a.exp)
    targets.to_csv(out / "summary_table.csv", index=False)
    (out / "summary_table.md").write_text("# Success targets (section 3.4)\n\n" + R.targets_markdown(targets), encoding="utf-8")
    (out / "summary_table.json").write_text(json.dumps(targets.to_dict("records"), indent=2, default=lambda o: None if o != o else str(o)))
    abl = R.collect_ablations(a.exp)
    abl.to_csv(out / "ablation_table.csv", index=False)
    (out / "ablation_table.md").write_text("# Ablations (section 8.4)\n\n" + R.to_markdown(abl), encoding="utf-8")
    faith, auroc = R.faithfulness_rows(a.exp), R.auroc_rows(a.exp)
    faith.to_csv(out / "faithfulness.csv", index=False); auroc.to_csv(out / "auroc.csv", index=False)
    overview_figure(targets, Path(a.figs) / "targets_overview.png")

    study = Path(a.study)
    if (study / "responses.csv").exists() and (study / "pairs.csv").exists():
        from truesight.analysis.user_study import analyse, fmt_markdown
        t, design = analyse(pd.read_csv(study / "responses.csv"), pd.read_csv(study / "pairs.csv"))
        t.to_csv(out / "user_study.csv", index=False)
        (out / "user_study.md").write_text(fmt_markdown(t, design) + "\n", encoding="utf-8")
        (out / "user_study.json").write_text(json.dumps({"design": design, "table": t.to_dict("records")}, indent=2, default=float))
    copied = 0 if a.no_copy else copy_results(a.exp, out)
    prov["files_copied"] = copied
    (out / "provenance.json").write_text(json.dumps(prov, indent=2))

    print(R.targets_markdown(targets))
    print(R.to_markdown(abl))
    print(f"wrote {out} ({copied} result files copied); commit {str(prov['commit'])[:10]}, frozen: {prov['frozen']}")


if __name__ == "__main__":
    main()
